int numBins = bins->numBins;
int numPrimitives = bins->numPrimitives;
T *binBuffer = bins->binBuffer;
real3<T> bminLocal = bmin;
real3<T> bmaxLocal = bmax;
int minCostAxisLocal = -1;
T minCost = std::numeric_limits<T>::max();
T cutPos[3];

for (int axis = 0; axis < 3; axis++) {
    T sa_b = (bmaxLocal[axis] - bminLocal[axis]) * (bmaxLocal[(axis + 1) % 3] - bminLocal[(axis + 1) % 3]) + (bmaxLocal[axis] - bminLocal[axis]) * (bmaxLocal[(axis + 2) % 3] - bminLocal[(axis + 2) % 3]);
    T leftSA = 0;
    T rightSA = sa_b;
    int leftCount = 0;
    int rightCount = numPrimitives;

    for (int i = 0; i < numBins; i++) {
        leftSA += (binBuffer[i * 3 + axis] - bminLocal[axis]) * 2;
        leftCount += binBuffer[i * 4];
        rightSA -= (binBuffer[i * 3 + axis] - bminLocal[axis]) * 2;
        rightCount -= binBuffer[i * 4];

        T cost = leftSA * leftCount + rightSA * rightCount;
        if (cost < minCost) {
            minCost = cost;
            minCostAxisLocal = axis;
            cutPos[axis] = binBuffer[i * 3 + axis];
        }
    }
}

*minCostAxis = minCostAxisLocal;
cut_pos[0] = cutPos[0];
cut_pos[1] = cutPos[1];
cut_pos[2] = cutPos[2];
return true;

